rows=RESULTS['rows']
for r in rows:
 r['label']=NAMES[r['model']];r['version']=MODELS[r['model']]['version'];r['checkpoint_sha256']=MODELS[r['model']]['runtime']['weights_sha256'];r['organization']=MODELS[r['model']]['organization'];r['organization_source']=MODELS[r['model']]['organization_source'];r['submitter']='Motion Challenge';r['status']='Trace verified';r['date']='2026-10-23';r['rank']=None;r['benchmark_id']='lafan40';r['robot_id']='g1-29dof';r.setdefault('track_id','lafan40-g1-nominal-v1')
(D/'data').mkdir(exist_ok=True)
TRACKS=json.loads((CONTENT/'tracks.json').read_text())
(D/'data/development-summary.json').write_text(json.dumps({'dataset':'LAFAN40','robot':'G1 29DoF','tracks':TRACKS,'rows':rows},indent=2))
nav=[('Overview','/'),('Benchmarks','/benchmarks/'),('Leaderboard','/leaderboard/'),('Models','/models/'),('Protocol','/protocol/'),('Submit','/submit/')]
def page(path,title,body,active):
 folder=D/path.strip('/');folder.mkdir(exist_ok=True,parents=True)
 links=''.join(f'<a href="{url}" '+('aria-current="page"' if label==active else '')+f'>{label}</a>' for label,url in nav)
 (folder/'index.html').write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · Motion Challenge</title><meta name="site-base-path" content="{BASE}"><meta name="results-revision" content="{RESULTS_REVISION}"><link rel="canonical" href="{SITE_URL}{path}"><meta name="description" content="Open, reproducible humanoid motion tracking evaluation. Shared protocols, independent model adapters, public review. LAFAN40 is our first dataset."><link rel="stylesheet" href="/style.css"><script src="/app.js?v={RESULTS_REVISION}" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="/"><span class="mark">m<span>c</span></span><span>Motion Challenge</span></a><nav aria-label="Main navigation">{links}</nav><a class="github" href="{GH}">GitHub ↗</a></header><main id="main">{body}</main><footer><div><a class="brand" href="/">Motion Challenge</a><p>Open evaluation. Reproducible evidence.</p></div><div><a href="{GH}/motion-challenge">Core repository ↗</a><a href="/submit/">Contribute a controller</a><a href="/about/">About &amp; acknowledgments</a><a href="{WEBSITE_SOURCE}">Website source ↗</a></div><small>Open protocols · Public evidence<br>Updated 23 October 2026</small></footer></body></html>''')
def intro(kicker,title,text):return f'<section class="pagehead"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lede">{text}</p></section>'
# Purpose-built schematic, not a robot rendering or reported motion trajectory.
figure='''<div class="hero-figure" aria-label="Schematic of reference and controller trajectories"><div class="figure-caption"><span class="dot"></span> ONE REFERENCE. MANY CONTROLLERS.</div><svg viewBox="0 0 650 500" role="img" aria-label="Two schematic robot poses with reference trajectories"><defs><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M 40 0 L 0 0 0 40" fill="none" stroke="#d5e2de" stroke-width=".7"/></pattern></defs><rect width="650" height="500" fill="url(#grid)"/><g fill="none" stroke-linecap="round" stroke-linejoin="round"><path d="M48 388 Q160 405 240 353 T440 320 T618 271" stroke="#8caf9f" stroke-width="2" stroke-dasharray="5 7"/><path d="M48 414 Q145 427 246 377 T442 347 T618 302" stroke="#125b50" stroke-width="3"/><g transform="translate(90 30)" stroke="#a9bdb5" stroke-width="8"><circle cx="190" cy="74" r="23"/><path d="M183 105 L159 184 L204 232 M179 116 L118 139 L101 190 M176 116 L223 154 L263 134 M159 184 L116 240 L84 318 M159 184 L197 248 L257 276"/><path d="M78 319 L103 321 M251 277 L274 277" stroke-width="12"/></g><g transform="translate(240 50)" stroke="#145b51" stroke-width="9"><circle cx="190" cy="74" r="23" fill="#f8faf7"/><path d="M184 105 L164 185 L205 222 M181 117 L130 153 L112 198 M181 117 L220 148 L265 131 M164 185 L131 247 L95 316 M164 185 L201 244 L255 277"/><path d="M90 316 L115 319 M250 277 L277 279" stroke-width="13"/></g></g><g fill="#e8f1ec" stroke="#145b51" stroke-width="2"><circle cx="404" cy="235" r="7"/><circle cx="441" cy="294" r="7"/><circle cx="371" cy="297" r="7"/><circle cx="421" cy="167" r="7"/></g><g font-family="monospace" font-size="12" fill="#667a73"><text x="36" y="465">REFERENCE → OBSERVATION → ACTION → EVIDENCE</text><text x="36" y="38">G1 / 29 DOF</text></g></svg><div class="figure-foot"><span><i class="line ref"></i>Reference</span><span><i class="line"></i>Controller</span><span>Schematic illustration</span></div></div>'''
page('/','Open humanoid evaluation',f'''<section class="hero"><div><p class="eyebrow">OPEN HUMANOID EVALUATION</p><h1>Measure motion.<br><em>Make it reproducible.</em></h1><p class="lede">A shared testing ground for general motion controllers. Compare full-motion success and tracking accuracy under explicit, inspectable conditions.</p><div class="actions"><a class="button" href="/leaderboard/">Explore the leaderboard <span>↗</span></a><a class="text-link" href="{GH}/motion-challenge">Get the evaluator ↗</a></div><p class="small">First dataset: <a href="/benchmarks/lafan40/">LAFAN40</a> · Unitree G1 · 29 DoF</p></div>{figure}</section><section class="stats"><div><strong>40</strong><span>complete motion clips</span></div><div><strong>10</strong><span>models evaluated</span></div><div><strong>3</strong><span>alignment views</span></div><div><strong>1</strong><span>shared evaluation core</span></div></section><section class="section"><div class="section-title"><p class="eyebrow">THE BENCHMARK COLLECTION</p><h2>Start with motion.<br>Build a common standard.</h2></div><a class="dataset-feature" href="/benchmarks/lafan40/"><div><span class="tag">DATASET 01</span><h3>LAFAN40</h3><p>Forty retargeted motion sequences. Every clip starts at its first frame and runs until completion or a declared failure.</p><span class="text-link">Explore dataset and protocol ↗</span></div><div class="dataset-number">40<small>motions · one checkpoint</small></div></a></section><section class="section tint"><p class="eyebrow">BUILT FOR INDEPENDENT REVIEW</p><h2>A score should come with evidence.</h2><div class="three"><article><span class="step">01</span><h3>One kernel</h3><p>Data, clocks, physics, termination and metrics are owned by a versioned core. Models bring their inference.</p></article><article><span class="step">02</span><h3>Faithful inference</h3><p>Check the author's normalization, history, control rate and action processing. Log adaptations; never silently tune a model for rank.</p></article><article><span class="step">03</span><h3>Inspectable results</h3><p>Bind checkpoints and source versions to a run. Recompute scores from pose traces, and make the reproduction record accessible.</p></article></div></section><section class="section split"><div><p class="eyebrow">PROJECT UPDATE · 23 OCT 2026</p><h2>The first LAFAN40 comparison.</h2></div><div><p>Ten public models have been evaluated on all 40 motions. Explore success, completion and tracking errors, with checkpoint provenance on every model page.</p><a class="text-link" href="/leaderboard/">Explore the results ↗</a></div></section>''','Overview')
page('/benchmarks/','Benchmarks',intro('THE BENCHMARK COLLECTION','One core. Many datasets.','Choose a dataset and a robot. Each combination defines a frozen suite and its own comparison track. Results from different physics or protocol versions are never mixed.')+'''<section class="section"><a class="dataset-feature" href="/benchmarks/lafan40/"><div><span class="tag">DATASET 01 · AVAILABLE</span><h2>LAFAN40</h2><p><span class="tag">UNITREE G1 · 29 DOF</span></p><p>Whole-body motion tracking on G1. Forty complete clips, no filtering by difficulty.</p><span class="text-link">Dataset, metrics and results ↗</span></div><div class="dataset-number">40<small>clips / G1 29DoF</small></div></a><div class="callout"><h3>Add the next benchmark</h3><p>A new dataset supplies its manifest, protocol and documentation. The shared kernel handles simulation and verification.</p><a href="/submit/#datasets">Dataset integration guide →</a></div></section>''','Benchmarks')
page('/benchmarks/lafan40/','LAFAN40',intro('DATASET 01 / G1 29DOF','LAFAN40','Full-length tracking of 40 LAFAN1 motions retargeted to Unitree G1. One checkpoint is evaluated across the complete suite.')+f'''<section class="stats"><div><strong>40</strong><span>clips · no filtering</span></div><div><strong>147.0</strong><span>minutes of reference motion</span></div><div><strong>30 Hz</strong><span>source frame rate</span></div><div><strong>29</strong><span>actuated joints</span></div></section><section class="section split"><div><h2>What this track measures</h2><p>Success means reaching the end without triggering the shared failure conditions. Tracking errors describe the observed prefix and must be read with completion. <a href="#failure-conditions">See failure conditions ↓</a></p><div class="actions"><a class="button" href="/leaderboard/">View LAFAN40 results ↗</a></div></div><dl class="facts"><div><dt>Reference</dt><dd>First frame to exact final timestamp</dd></div><div><dt>Evaluation</dt><dd>Nominal · no noise or randomization · friction 1</dd></div><div><dt>Physics</dt><dd>Canonical G1 · MuJoCo · 2 ms step</dd></div><div><dt>Policy clock</dt><dd>Native controller frequency</dd></div><div><dt>Metric clock</dt><dd>50 Hz, plus the exact endpoint</dd></div><div><dt>State access</dt><dd>Privileged-state-v0</dd></div></dl></section><section class="section" id="failure-conditions"><p class="eyebrow">SUCCESS &amp; FAILURE</p><h2>When does a motion end?</h2><p>A clip passes only when it reaches the exact final reference timestamp without a failure. All 40 clips use the same checkpoint, and each starts from the first reference pose and velocity.</p><div class="table-scroll"><table class="failure-table"><thead><tr><th>Condition</th><th>Compared at the same timestamp</th><th>Failure threshold</th></tr></thead><tbody><tr><td>Torso height</td><td>Absolute world-Z difference between actual and reference <code>{FAIL['anchor_body']}</code></td><td>&gt; {FAIL['anchor_height_m']:g} m</td></tr><tr><td>Torso tilt</td><td>Absolute difference of the Z components of unit gravity projected into the actual and reference torso frames</td><td>&gt; {FAIL['gravity_z']:g}</td></tr><tr><td>Wrist or ankle height</td><td>Largest absolute world-Z difference across the left/right wrists and ankles</td><td>&gt; {FAIL['end_effector_height_m']:g} m</td></tr></tbody></table></div><p><strong>Any one condition ends the clip.</strong> Checks run at {1/PROTOCOL['metric_period_s']:g} Hz after physics, plus the exact endpoint. The comparison is strictly greater-than: a value equal to the threshold does not trigger failure. A failure at the final timestamp still counts as a failed clip.</p><div class="three"><article><h3>Relative to the reference</h3><p>Height means tracking error, not a minimum standing height. A reference that lies down or contacts the floor is not automatically a failure. Gravity uses the unit vector (0, 0, −1); the 0.8 threshold is dimensionless, not radians or degrees.</p></article><article><h3>Alignment affects metrics</h3><p>XY and yaw alignment apply only to reported tracking errors. They do not change the simulated state or the failure checks. There is no additional XY, yaw, keybody-distance or contact threshold for success.</p></article><article><h3>Completion and errors</h3><p>Completion is the last valid sample time divided by the clip duration. Tracking errors include the failing sample. Invalid numerical states, inference errors and truncated smoke runs cannot produce a successful full-suite result.</p></article></div><details><summary>Exact bodies, formula and source</summary><p>Height endpoints: <code>left_wrist_yaw_link</code>, <code>right_wrist_yaw_link</code>, <code>left_ankle_roll_link</code> and <code>right_ankle_roll_link</code>.</p><p>For torso rotation R from local to world and g = (0, 0, −1), projected gravity is Rᵀg. The tilt check is |(R<sub>actual</sub>ᵀg)<sub>z</sub> − (R<sub>reference</sub>ᵀg)<sub>z</sub>| &gt; 0.8. It measures agreement with the reference tilt, not heading or the full 3D angular distance.</p><a href="{GH}/motion-challenge/blob/main/suites/lafan/protocol.cpu-development-v1.json">Protocol configuration ↗</a> · <a href="{GH}/motion-challenge/blob/main/src/motion_challenge/physics.py#L133">Failure implementation ↗</a></details></section><section class="section tint"><p class="eyebrow">DATA PROVENANCE</p><h2>Fixed input, inspectable protocol.</h2><p>The dataset is sourced from <a href="https://huggingface.co/datasets/lvhaidong/LAFAN1_Retargeting_Dataset">lvhaidong/LAFAN1_Retargeting_Dataset</a>. The manifest pins revision <code>ce1572906efe6157840e8474d5a0d7aa87481e74</code>, file sizes and SHA256 values.</p><p>264,705 source frames; total reference duration 8,822.1667 seconds. Retargeted references are used as supplied. This is a tracking benchmark, not a claim that every reference is physically feasible or unseen during training.</p><a class="text-link" href="{GH}/motion-challenge/blob/main/suites/lafan/dataset.json">Inspect the frozen manifest ↗</a></section>''','Benchmarks')
# Scores retain their original reproduction records; pagination is presentation only.
page('/leaderboard/','Leaderboard',intro('BENCHMARK RESULTS','The leaderboard','Full-motion success first. Tracking accuracy with coverage. Compare organizations, checkpoints and tracking performance under one shared protocol.')+'''<section class="board-section"><div class="track-selectors"><label>Benchmark<select id="benchmark-select" aria-label="Benchmark"></select></label><label>Robot<select id="robot-select" aria-label="Robot"></select></label><label>Protocol<select id="protocol-select" aria-label="Protocol"></select></label><a id="track-details" href="/benchmarks/lafan40/">Dataset &amp; failure conditions ↗</a></div><div class="toolbar"><p id="track-caption" class="small">Loading benchmark…</p><label class="search">Find a model <input id="model-search" type="search" placeholder="Model, version or organization…"></label></div><div class="table-scroll"><table id="leaderboard"><thead><tr><th>Rank</th><th>Model</th><th>Organization</th><th><button data-sort="passed">Success ↑</button></th><th><button data-sort="completion_pct">Completion ↑</button></th><th><button data-sort="mpjpe_xy_yaw_aligned_m">XY + yaw ↓ <small>mm</small></button></th><th><button data-sort="mpjpe_xy_aligned_m">XY only ↓ <small>mm</small></button></th><th><button data-sort="mpjpe_world_m">No alignment ↓ <small>mm</small></button></th></tr></thead><tbody></tbody></table><p id="empty" hidden>No models match your search.</p></div><div class="pagination"><label>Models per page <select id="page-size"><option value="5">5</option><option value="10" selected>10</option><option value="15">15</option><option value="25">25</option></select></label><div><span id="page-range" aria-live="polite"></span><button id="previous-page" aria-label="Previous page">← Previous</button><button id="next-page" aria-label="Next page">Next →</button></div></div><p class="table-note">MuJoCo 3.17.0 batch reruns are underway for all 12 integrated models. Engine versions have separate protocol selections; scores are not mixed. <a href="https://github.com/motion-challenge-project/motion-challenge/commit/7ba33e4">Published evaluator ↗</a></p><p class="table-note"><strong>Shared rules. Public code. Reproducible runs.</strong> Within each benchmark, robot and protocol, the core fixes data, physics, failures and scoring. Each entry identifies its checkpoint and inference implementation.</p><p class="table-note">Default order: complete clips, then macro completion. Position errors are macro means over observed prefixes, including the failure frame. Lower error with earlier failure is not necessarily better.</p><a class="text-link" href="/data/development-summary.json" download>Download results (JSON) ↓</a></section><section class="section three"><article><h3>Success</h3><p>A clip passes only if it reaches the final reference frame without any declared failure. All 40 clips use the same checkpoint.</p></article><article><h3>Completion</h3><p>Mean fraction of motion completed before failure. Kept beside errors so short, easy prefixes cannot hide poor coverage.</p></article><article><h3>Three alignments</h3><p>XY + yaw measures pose shape; XY keeps heading error; no alignment keeps global drift. Height is retained in all three.</p><a href="/protocol/#alignment">Metric definitions →</a></article></section>''','Leaderboard')
cards=''.join(f'<a class="model-card" href="/models/{k}/"><span class="tag">G1 / CHECKPOINT ADAPTER</span><h2>{v}<span>↗</span></h2><p>{html.escape(MODELS[k]["organization"])}</p></a>' for k,v in NAMES.items())
cards+=''.join(f'<a class="model-card" href="/models/{c["id"]}/"><span class="tag">PUBLIC CHECKPOINT · INTEGRATION PENDING</span><h2>{html.escape(c["display_name"])}<span>↗</span></h2><p>{html.escape(c["organization"])}</p></a>' for c in CANDIDATES)
page('/models/','Model directory',intro('INDEPENDENT MODEL ADAPTERS','Bring a checkpoint.',f'{len(MODELS)+len(CANDIDATES)} checkpoint entries across {len(set([m["family"] for m in MODELS.values()]+[c["family"] for c in CANDIDATES]))} model families; {len(set(r["model"] for r in rows))} have full LAFAN40 results. Each version is listed separately and uses its own adapter repository when integrated. New checkpoints receive scores after full-suite evaluation.')+f'<section class="section model-grid">{cards}</section>','Models')
for r in sorted(rows, key=lambda row: row.get('mujoco_version','3.16.0')):
 k=r['model'];rt=MODELS[k]['runtime'];pr=MODELS[k]['provenance']
 repo_link=(f'<a class="button" href="{GH}/motion-challenge-{k}">Adapter repository ↗</a>' if MODELS[k].get('repository_available') else '<span class="small">Independent adapter source publication in progress.</span>')
 detail=f'''<section class="section split"><div><h2>Reproduction record</h2><p>This is a Motion Challenge adaptation of the public model. The authors have not submitted or endorsed this evaluation.</p><div class="actions">{repo_link}<a class="text-link" href="{pr['upstream']}">Author source ↗</a></div><h3>Install and run</h3><pre><code>git clone --recurse-submodules {GH}/motion-challenge-{k}.git
cd motion-challenge-{k}
uv sync
uv run evaluate.py</code></pre><p class="small">Checkpoint reuse and hash checking are automatic. The core owns dataset fetching and scoring. See the repository for artifact preparation requirements.</p></div><dl class="facts"><div><dt>Organization</dt><dd>{html.escape(MODELS[k]["organization"])}</dd><dt>Evaluation by</dt><dd>Motion Challenge</dd></div><div><dt>Model version / checkpoint</dt><dd>{html.escape(MODELS[k]["version"])}</dd><dd class="small">{html.escape(MODELS[k]["version_kind"])}</dd></div><div><dt>Inference period</dt><dd>{rt['control_period_s']*1000:g} ms</dd></div><div><dt>Reference preview</dt><dd>{rt['reference_preview_s']*1000:g} ms</dd></div><div><dt>Checkpoint SHA256</dt><dd><code>{rt['weights_sha256']}</code></dd></div><div><dt>Author source revision</dt><dd><code>{pr['source_commit'] or 'Revision audit pending'}</code></dd></div><div><dt>Core</dt><dd>Pinned motion-challenge submodule</dd></div></dl></section><section class="section tint"><p class="eyebrow">LAFAN40 · UNITREE G1 · 29 DOF</p><h2>{r['passed']} / 40 motions passed</h2><p><a href="/benchmarks/lafan40/">LAFAN40 benchmark</a> · Nominal · MuJoCo {r.get('mujoco_version', '3.16.0')} · Full-length evaluation · 23 October 2026</p><p>Macro completion: {r['completion_pct']:.2f}%. No observation noise or randomization; friction 1. See the <a href="/benchmarks/lafan40/#failure-conditions">failure conditions</a> and all three alignment metrics in the <a href="/leaderboard/?benchmark=lafan40&amp;robot=g1-29dof">leaderboard</a>.</p><a class="text-link" href="/data/evidence/{r.get('evidence_file', k+'.json')}">Inspect per-motion results and receipt (JSON) ↓</a><p class="small">Complete LAFAN40 run with independently recomputed failures and metrics. The linked receipt pins the evaluated source revision and MuJoCo {r.get('mujoco_version', '3.16.0')}. Current adapter main uses MuJoCo 3.17.0 batch; select its separate protocol to compare new results. Trace verification checks recorded poses; it is not a security attestation.</p></section>'''
 if not MODELS[k].get('repository_available'):
  start=detail.index('<h3>Install and run</h3>');end=detail.index('</div><dl',start)
  detail=detail[:start]+'<p>Native inference passed a short execution check. The full LAFAN40 rerun is running; the source repository will be linked here when publication completes.</p>'+detail[end:]
 page('/models/'+k+'/',NAMES[k],intro('MODEL / LAFAN40',NAMES[k],'Checkpoint-specific inference, explicit provenance, shared evaluation.')+detail,'Models')
for c in CANDIDATES:
 links=''.join(f'<li><a href="{a["url"]}">{html.escape(a["name"])} ↓</a>'+ (f'<br><code>{a["sha256"]}</code>' if a.get('sha256') else '')+'</li>' for a in c['artifacts'])
 page('/models/'+c['id']+'/',c['label'],intro('PUBLIC CHECKPOINT / G1 29DOF',c['display_name'],c['architecture'])+f'<section class="section split"><div><h2>Checkpoint and source</h2><p>{html.escape(c["notes"])}</p><div class="actions"><a class="button" href="{c["upstream"]}">Author source ↗</a><a class="text-link" href="{c["project_url"]}">Project details ↗</a></div><h3>Released artifacts</h3><ul>{links}</ul></div><dl class="facts"><div><dt>Organization</dt><dd>{html.escape(c["organization"])}</dd></div><div><dt>Version / checkpoint</dt><dd>{html.escape(c["version"])}</dd></div><div><dt>Source revision</dt><dd><code>{c["source_commit"]}</code></dd></div><div><dt>Robot</dt><dd>Unitree G1 · 29 DoF</dd></div><div><dt>Planned benchmark</dt><dd><a href="/benchmarks/lafan40/">LAFAN40 · Nominal v1</a></dd></div></dl></section><section class="section tint"><h2>LAFAN40 evaluation</h2><p>Public checkpoint located. An independent adapter is planned for this exact version; full-suite evaluation is pending and no score has been assigned. Versions do not share or inherit evaluation scores.</p></section>','Models')
page('/protocol/','Evaluation protocol',intro('METHODS & REVIEW','What a score means.','A versioned protocol separates model inference from the conditions under which it is measured.')+f'''<div class="docs-layout"><aside><a href="#contract">Evaluation contract</a><a href="#alignment">Alignment metrics</a><a href="#inference">Author inference</a><a href="#evidence">Evidence & limits</a></aside><article class="docs"><section id="contract"><h2>01 · A fixed evaluation contract</h2><p>The current core uses official <code>mujoco.batch</code> with MuJoCo 3.17.0. Every model keeps its native policy clock and independent history; PD is recomputed every physics step. Download and evaluation progress is emitted every five seconds. Earlier MuJoCo 3.16.0 results remain in a separate protocol selection.</p><p>The core controls source data, interpolation, robot asset, physics, reset state, clocks, termination and scoring. The adapter controls observations, native history/recurrent state, network inference and action processing.</p><p>LAFAN40 starts from the first reference pose and velocity. Every clip runs to its exact last timestamp unless a failure occurs. Reference queries outside the clip are clamped without shortening the episode. No evaluation noise or randomization; friction is 1.</p><h3>Failure conditions</h3><ul><li>Absolute torso height error exceeds 0.25 m.</li><li>Reference-versus-actual projected-gravity Z difference exceeds 0.8.</li><li>Maximum wrist or ankle world-height error exceeds 0.25 m.</li></ul><p>See <a href="/benchmarks/lafan40/#failure-conditions">LAFAN40 failure conditions</a> for formulas, exact bodies and endpoint behavior. No additional XY or tracking-precision threshold is introduced. The complete suite and one checkpoint are required. A smoke truncation or infrastructure failure cannot be counted as a passed motion.</p></section><section id="alignment"><h2>02 · Three views of tracking error</h2><div class="metric-box"><h3>XY + yaw alignment</h3><p>Remove per-frame horizontal root translation and relative world-Z heading before measuring 14 keybody positions. Retain height and tilt. This describes local body tracking with horizontal trajectory and heading factored out.</p></div><div class="metric-box"><h3>XY alignment</h3><p>Remove only per-frame root XY translation. Retain heading, height and tilt, so a heading mismatch remains visible.</p></div><div class="metric-box"><h3>No alignment</h3><p>Compare world-frame body positions directly. Global translation and heading drift remain in the result.</p></div><p>Each score is the mean Euclidean body-position distance in millimetres. The core names these fields MPJPE; they use body origins, not joint-angle differences. Joint MAE is separately measured in radians.</p><p>The XY + yaw transform uses the closest relative world-Z rotation derived from both pelvis orientations. Degenerate headings are flagged, never silently dropped. See the implementation for the exact formula.</p><h3>Coverage is part of the interpretation</h3><p>Errors average the observed prefix, including the failing sample. First average frames within a motion, then motions within the suite. A model that fails early can have low prefix error; always compare success and completion alongside it.</p></section><section id="inference"><h2>03 · Follow the author's inference</h2><p>Pin the source and checkpoint. Check observations, joint order, coordinate frames, control frequency, reference lookahead, normalization, history initialization, recurrent memory, action scales, clipping, gains and filters. Compare input tensors, raw network outputs and final motor targets on identical sequences, including reset and endpoint cases.</p><p>Document benchmark-specific differences. A shared robot and physics protocol can differ from an author's training environment; matching inference does not reproduce their paper scores. Checkpoint conversion requires a numerical equivalence test.</p></section><section id="evidence"><h2>04 · Separate review gates</h2><ol><li><strong>Artifact provenance:</strong> fixed checkpoint, source revision and dependency lock.</li><li><strong>Inference parity:</strong> tested against author-maintained inference.</li><li><strong>Complete evaluation:</strong> every clip under one protocol and checkpoint.</li><li><strong>Trace verification:</strong> independently recompute failures and metrics.</li></ol><p>Admitted results require all gates and public reproducibility evidence. No current historical development entry is marked admitted. Trace consistency alone does not prove the claimed controller ran; the current separate-process worker is not a security sandbox.</p><a class="text-link" href="{GH}/motion-challenge/blob/main/docs/PROTOCOL.md">Read the implementation-level protocol ↗</a></section></article></div>''','Protocol')
page('/submit/','Submit a controller',intro('CONTRIBUTE TO THE BENCHMARK','Make your result reproducible.','A model repository, a pinned checkpoint, and a verifiable run. LAFAN40 is the first suite; the integration contract is shared.')+f'''<section class="section three steps"><article><span class="step">01</span><h3>Adapt inference</h3><p>Create your own repository with the core as a root-level submodule. Implement reset, act and close. Preserve the author's deployment behavior.</p><a href="{GH}/motion-challenge/blob/main/docs/ADAPTERS.md">SDK and adapter guide ↗</a></article><article><span class="step">02</span><h3>Run the whole suite</h3><p>Use one checkpoint and the fixed protocol. Keep outputs outside Git. Submit full pose traces, hashes, receipts and inference-parity evidence.</p><a href="/protocol/">Read the review requirements →</a></article><article><span class="step">03</span><h3>Request review</h3><p>Open an issue linking your adapter and external result artifacts. Include the actual submitter, source/checkpoint versions, training-data overlap and any adaptations.</p><a href="{GH}/motion-challenge/issues/new">Open a submission issue ↗</a></article></section><section class="section tint"><h2>A small adapter. A shared kernel.</h2><pre><code>motion-challenge-your-model/
├── motion-challenge/  # pinned core submodule
├── adapter.py         # inference only
├── runtime.json       # clocks, artifacts, input contract
├── provenance.json    # source and review evidence
├── evaluate.py        # shared core entrypoint
├── pyproject.toml
└── uv.lock</code></pre><p>The core owns datasets, physics, metrics and verification. Model repositories do not copy or override evaluation logic. Checkpoints, data and results live in local caches or external artifact storage.</p></section><section class="section" id="datasets"><h2>Propose another dataset</h2><p>Publish a manifest with immutable source revisions, file hashes, frame rate, joint order and the complete motion set. Define a distinct protocol version and benchmark identity. Preserve difficult clips, document licensing and overlap, and keep scores in their own track.</p><a class="text-link" href="{GH}/motion-challenge/blob/main/docs/BENCHMARKS.md">Dataset integration contract ↗</a></section>''','Submit')
page('/about/','About the project',intro('ABOUT MOTION CHALLENGE','Open evaluation, open scrutiny.','An independent open-source project for comparing general humanoid motion controllers with inspectable protocols and reproducible evidence.')+f'''<section class="section docs"><h2>What we are building</h2><p>A collection of benchmarks with one reusable core and independent model adapters. LAFAN40 on G1 29DoF is the first dataset. We publish the evaluation code and distinguish maintainer reproductions from author submissions.</p><p>Every metric follows the same rules within its benchmark, robot and protocol. The evaluation code is public, checkpoint and source revisions are pinned, and results have reproduction commands and per-motion evidence. Author-specific observations, control frequency and action processing are documented separately. Results are tied to checkpoint and protocol versions. Corrections should remain visible, with previous versions retained. Questions about an adaptation or score belong in the public issue tracker.</p><a class="button" href="{GH}/motion-challenge/issues">Discuss a result ↗</a><h2>Acknowledgments</h2><p>We thank the authors of the released controllers, LAFAN1 and the LAFAN1 retargeting dataset, MuJoCo and mjlab. Model names identify upstream work, not endorsement of this benchmark.</p><p>The site's organization was informed by the separation of protocol, aggregate results and task detail in <a href="https://robotwin-platform.github.io/leaderboard">RoboTwin</a>, the benchmark and documentation structure of <a href="https://robocasa.ai/">RoboCasa</a>, the public evaluation presentation of <a href="https://robochallenge.ai/home">RoboChallenge</a>, and <a href="https://github.com/Roboparty/MimicLite">MimicLite's project documentation</a>. This project is independent of those teams.</p><h2>Current limitations</h2><p>The current track uses privileged simulator state and nominal canonical physics. Inference reviews and independent adapter reruns are in progress. Historical development scores do not establish real-world performance or generalization beyond this dataset.</p></section>''','Overview')
